gold.schema_ddl:
CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT,
    data_registrazione DATE DEFAULT CURRENT_DATE
);

CREATE TABLE tbl_vend (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_vendita DATE NOT NULL,
    ricavo_operativo NUMERIC(12,2) CHECK (ricavo_operativo >= 0)
);

CREATE TABLE righe_vendita (
    id INT PRIMARY KEY,
    vendita_id INT NOT NULL REFERENCES tbl_vend(id),
    descrizione_prodotto TEXT NOT NULL,
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);
